/**
 * Apple Root CA - G3, the root every App Store Server API signature chains to.
 *
 * Shipped so verification is on without configuration. Public, from
 * https://www.apple.com/certificateauthority/AppleRootCA-G3.cer, valid until
 * 2039-04-30; tests/storekit-verify.test.ts pins its SHA-256 fingerprint.
 */
export const APPLE_ROOT_CA_G3 = Buffer.from(
  '',
  'base64'
);
